# AI Office v2.6 Part G Controlled Memory Capture Installer
$ErrorActionPreference="Stop"
$Repository="E:\AI\AI-Office"
Set-Location $Repository
$Stamp=Get-Date -Format "yyyyMMdd-HHmmss"
$Backup=Join-Path $Repository ("workspace\installer-backups\v2.6-part-g-"+$Stamp)
New-Item -ItemType Directory -Path $Backup -Force|Out-Null
function Write-EmbeddedFile{
 param([string]$RelativePath,[string]$Data)
 $Dest=Join-Path $Repository $RelativePath
 New-Item -ItemType Directory -Path (Split-Path -Parent $Dest) -Force|Out-Null
 if(Test-Path $Dest){
  $B=Join-Path $Backup $RelativePath
  New-Item -ItemType Directory -Path (Split-Path -Parent $B) -Force|Out-Null
  Copy-Item $Dest $B -Force
 }
 [IO.File]::WriteAllBytes($Dest,[Convert]::FromBase64String($Data))
 Write-Host "[WRITTEN] $RelativePath" -ForegroundColor Green
}
Write-EmbeddedFile -RelativePath "config\memory\capture-policy.json" -Data ""
Write-EmbeddedFile -RelativePath "scripts\memory\Get-AIOfficeExplicitMemoryCapture.ps1" -Data ""
Write-EmbeddedFile -RelativePath "scripts\memory\Save-AIOfficeExplicitConversationMemory.ps1" -Data ""
Write-EmbeddedFile -RelativePath "scripts\memory\Test-AIOfficeControlledMemoryCapture.ps1" -Data ""
Write-EmbeddedFile -RelativePath "docs\AI-Office-v2.6-Part-G-Controlled-Memory-Capture.md" -Data ""
$Scripts=Get-ChildItem "E:\AI\AI-Office\scripts\memory\*.ps1" -File
foreach($Script in $Scripts){$T=$null;$E=$null;[System.Management.Automation.Language.Parser]::ParseFile($Script.FullName,[ref]$T,[ref]$E)|Out-Null;if($E.Count-gt0){throw ("Syntax error in "+$Script.FullName+": "+(($E|ForEach-Object{$_.Message})-join"; "))}}
Write-Host ""
Write-Host "AI Office v2.6 Part G Controlled Memory Capture installed successfully." -ForegroundColor Green
Write-Host "Production conversation runtime was not modified." -ForegroundColor Yellow
Write-Host "Backups: $Backup" -ForegroundColor Cyan